import{_ as p}from"./chunks/f5d628f74eba71b1359f.B3btxn6o.js";import{_ as r,C as t,o as i,c as o,j as a,a as n,E as h,a5 as s}from"./chunks/framework.DNkHA0lr.js";const k=JSON.parse('{"title":"为什么你总是感到不堪重负","description":"","frontmatter":{"title":"为什么你总是感到不堪重负","originalTitle":"Why You Always Feel Overwhelmed","date":"2022-08-20","originalUrl":"https://thedankoe.com/letters/why-you-always-feel-overwhelmed/","minutes":8,"sourceHash":"46bdbcdde7056435e9712bb545cca1d2e5c921d4122f7e7f8ff8103888b76593","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/why-you-always-feel-overwhelmed/"}]]},"headers":[],"relativePath":"letters/why-you-always-feel-overwhelmed.md","filePath":"letters/why-you-always-feel-overwhelmed.md"}'),d={name:"letters/why-you-always-feel-overwhelmed.md"};function u(m,e,c,f,_,b){const l=t("ArticleMeta");return i(),o("div",null,[e[0]||(e[0]=a("h1",{id:"为什么你总是感到不堪重负",tabindex:"-1"},[n("为什么你总是感到不堪重负 "),a("a",{class:"header-anchor",href:"#为什么你总是感到不堪重负","aria-label":'Permalink to "为什么你总是感到不堪重负"'},"​")],-1)),h(l),e[1]||(e[1]=s('<p><a href="https://www.youtube.com/embed/yK4frWWTyqs?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我在以下每类人身上都注意到了<strong>一个共同的模式</strong>：</p><ul><li>成功的企业家</li><li>觉悟的精神导师</li><li>幸福的已婚夫妇</li><li>打破纪录的运动员</li></ul><p>什么模式？</p><p><strong>专注。</strong></p><p>我曾听到上述每个类别中的某个人提到，“专注”是他们获得成功、幸福和进步的关键。</p><p>在狂啃了关于表现、幸福、商业、灵性、哲学以及任何与享受生活相关的书籍之后……我想我找到了答案。</p><p>也就是最大化享受生活的关键（而你在任何努力中所取得的成功，都只是它的副产品）。</p><blockquote><p>一个人无论“外部”实际发生了什么，仅仅通过改变意识的内容，就能让自己感到幸福或痛苦。——米哈里·契克森米哈赖 (Mihaly Csikszentmihaly)</p></blockquote><p><em>专注</em>，就是受控的意识。</p><p>或者说，专注就是控制“意识的内容”。</p><p>当你的意识内容，也就是你所关注的事物，能够以积极的方式被理解时；你的生活就会变得积极。</p><p>意思是，如果你在任何特定情况下，都能努力从有利的视角获得清晰、无偏见的认知，你就会感觉棒极了。</p><p>这也让我想起了 Actualized.org 的里奥（Leo）提出的一个观点，即<em>一切</em>都是意识的虚构产物。例如：原子就是意识的虚构产物。它是当我们意识到某事物时，为了理解它而创造的一个标签。这稍微有点形而上学，但建立这种联系是很有趣的。</p><p>通过保持对单个“意识虚构产物”的专注——而不是在10个虚构产物之间分散注意力——我们就能过上快乐、健康且充实的生活。</p><h2 id="意识的内容" tabindex="-1">意识的内容 <a class="header-anchor" href="#意识的内容" aria-label="Permalink to &quot;意识的内容&quot;">​</a></h2><p>我想让你把自己的大脑想象成一台超级计算机。</p><p>你处理信息的能力取决于几个因素，但我想让你把注意力放在你的内存（RAM）上。</p><p>RAM——或称“随机存取存储器”——是计算机最重要的部件之一，它决定了性能。</p><p>你运行的不同程序、打开的浏览器标签页越多，以及运行内容的性能要求越高，你消耗的内存就越多，你的运行速度也就越慢。</p><p>这和你的专注力，即你在意识注意力中所保持的东西，没有任何不同。</p><p><a href="https://open.spotify.com/embed/episode/7EYNhtS8V9nKf5nFu7Dg2v?si=b879bc78f56c4965&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>人类每秒可以处理126比特的信息。在你的一生中，这加起来高达1850亿比特的信息。</p><p>大多数人的生活中同时运行着多个高负荷的“程序”，这些程序正在榨干他们有限的创造性能量。</p><ul><li>对过去令人后悔的错误的思绪</li><li>对未来充满压力的事件的思绪</li><li>为了逃避这些思绪而产生的对饥饿和娱乐的渴望</li><li>想要打破条件反射式生活方式的内心呐喊</li><li>一系列需要完成、优先级混乱的任务清单</li><li>本该完成却忘记了的任务所形成的开放式死循环</li></ul><p>这个清单没完没了。</p><p>现代人的头脑在默认情况下，注意力就会被分散到无数个方向。我们顶着压力生活，几乎处于病态。我们没有全神贯注、无忧无虑地活在当下，反而恰恰相反。我们生活在由分散的注意力创造的虚假现实中。</p><p>当我们在意识内容中占据了太多关于过去或未来的东西时，混乱就会随之而来。头脑往往会走向无序。如果不加以控制，我们就会失去对生活的掌控感，而正是这种掌控感能带来享受。这可以通过受控的意识来实现。</p><p>也就是，专注。</p><h2 id="夺回专注力的8个步骤" tabindex="-1">夺回专注力的8个步骤 <a class="header-anchor" href="#夺回专注力的8个步骤" aria-label="Permalink to &quot;夺回专注力的8个步骤&quot;">​</a></h2><p>要想打破我们机械化的生活方式，我们首先必须意识到它是如何影响我们生活的。</p><p>从混乱到有序，我们必须将注意力拉回中心，并选择真正值得关注的事物。</p><p>我们消耗的内存越少——我们的专注力越集中——生活就越令人享受。秩序回归，对生活的掌控感会让我们对生活本身产生深深的满足感。</p><p><img src="'+p+'" alt=""></p><h3 id="_1-选择你生活中的一个滞后领域" tabindex="-1">1) 选择你生活中的一个滞后领域 <a class="header-anchor" href="#_1-选择你生活中的一个滞后领域" aria-label="Permalink to &quot;1) 选择你生活中的一个滞后领域&quot;">​</a></h3><p>我们的强度取决于我们最薄弱的一环。那些最滞后的领域往往藏着最容易摘到的果实。正是这些领域引发了最多的问题。</p><p>想一想，我生活中的哪个领域一直在引发问题，以至于如果这些问题得到解决，你的生活质量将会直线飙升。</p><p>金钱？约会？心理健康？自尊？社交生活？健康和能量水平？去散个步，沉思一下，然后选择那个一旦修复，其结果就会在你的生活其他领域产生连锁反应的领域。</p><p>为了这篇文章的连贯性，也因为这是许多人的共同问题，我们把<em><strong>金钱</strong></em>作为滞后领域来谈谈。</p><h3 id="_2-理清基本面" tabindex="-1">2) 理清基本面 <a class="header-anchor" href="#_2-理清基本面" aria-label="Permalink to &quot;2) 理清基本面&quot;">​</a></h3><p>我想区分一下这两个概念：</p><ul><li>基础、原则或基本面</li><li>策略、小技巧和技术细节。</li></ul><p>基本面驱动结果。技术细节可以推动结果，但前提是你必须已经掌握了基本面、将其系统化，并将其变成习惯。</p><p>基本面能撬动杠杆。技术细节则容易带来陷阱、让人感到不堪重负，并凭空制造出原本不存在的问题。</p><p>对于我们关注的金钱领域，你需要流量（traffic）和报价/产品（offer）。这是获得你想要之物的通用原则。</p><p>如果你没有流量：</p><ul><li>社交媒体受众</li><li>付费广告或推广</li><li>一个社区或社群</li><li>自然搜索结果</li><li>直接联系（即冷邮件）</li></ul><p>就没人会看到你的报价。</p><p>如果你没有一个引人注目的报价：</p><ul><li>数字或实体产品</li><li>自由职业或咨询服务</li><li>基于群组的课程或在线辅导</li><li>会员服务或社区</li></ul><p>你就会陷入无处引导流量的境地。</p><p>就像如果你身处相亲市场。</p><p>如果你是一个高价值的“产品”，但却没有把自己置于高“流量”的环境中，那祝你好运了。</p><h3 id="_3-设定基于能力的目标" tabindex="-1">3) 设定基于能力的目标 <a class="header-anchor" href="#_3-设定基于能力的目标" aria-label="Permalink to &quot;3) 设定基于能力的目标&quot;">​</a></h3><p>专注于让自己看起来更好、获得更多粉丝、得到最高互动率、拥有最火辣的伴侣等等，这并没有错。它们有其用武之地，也是有益的。我建议关注这些，但不要把它们作为你的主要焦点。</p><p><strong>问题在于：</strong> 虚荣型目标比能力型目标更难被我们掌控。</p><p>这些步骤并不是线性的，除非你了解到自己在日常中可以采取哪些能撬动杠杆的行动，否则很难设定一个基于能力的目标。</p><p>在我们的例子中，如果我想建立受众（流量）并销售数字产品（报价）来赚钱——你需要执行类似以下的杠杆行动：</p><ul><li>每天写3篇短帖子（比如推文）</li><li>每周写1篇长文章（通讯/博客）</li><li>将那篇长文章浓缩成一篇中篇帖子（比如推特长文或 LinkedIn 帖子）</li><li>花30-60分钟为你的数字产品编写课程大纲</li></ul><p>在这种情况下，你可以设定一个每天写1000个高质量字数的目标，并根据写作本身来评估自己（而不是评估写作带来的结果）。</p><p>过程大于结果。</p><p>说到写作，这就是我们在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《2小时作者》（The 2 Hour Writer）</a> 中探讨的所有内容。</p><h3 id="_4-开始之后再自我教育" tabindex="-1">4) 开始之后再自我教育 <a class="header-anchor" href="#_4-开始之后再自我教育" aria-label="Permalink to &quot;4) 开始之后再自我教育&quot;">​</a></h3><p>基本面能让你入门，但你需要学习如何将这些基本面应用到你的具体情况中。</p><p>太多人陷入了“教程地狱”，试图吸收尽可能多的信息，却从未真正开始。</p><p>相反，你应该：</p><ul><li>快速开始并快速失败</li><li>找出导致你失败的原因</li><li>寻找特定的信息来克服它</li><li>再次失败，让经验随着时间产生复利</li></ul><p>别再试图在开始之前弄清楚一切了。那叫精神意淫。</p><h3 id="_5-每天留出30-60分钟" tabindex="-1">5) 每天留出30-60分钟 <a class="header-anchor" href="#_5-每天留出30-60分钟" aria-label="Permalink to &quot;5) 每天留出30-60分钟&quot;">​</a></h3><p>深度工作不仅适用于工作。它适用于你生活的方方面面。</p><p>当企业家想在商业上取得进展时，他们会投入时间和精力来促成这种进展。</p><p>当已婚夫妇想在关系上取得进展时，他们会为彼此投入时间。</p><p>当个体想在心智上取得进展时，他们会把时间投入到独处和意识练习上——比如冥想。</p><p><em>无论在哪个生活领域，到了需要投入“深度工作”的时候，都必须创造免受干扰的时间，这样你的注意力才不会被分散。</em></p><h3 id="_6-沉浸在该目标的内容中" tabindex="-1">6) 沉浸在该目标的内容中 <a class="header-anchor" href="#_6-沉浸在该目标的内容中" aria-label="Permalink to &quot;6) 沉浸在该目标的内容中&quot;">​</a></h3><p>对于有灵性倾向的人来说，这就是“临在”。</p><p>对其他人而言，这被称为“全情投入”，并进入某种程度的心流状态。</p><p>想想当你刷社交媒体时，你是如何将全部注意力都放在手机上的。营销人员和科技公司拥有整个团队，专门致力于通过捕获注意力来触发一种伪心流状态。</p><p>当你被吸进手机里时，你的注意力中就再也装不下其他东西了。大多数人利用这一点来逃避现实，而不是去探寻现实本身。</p><p>如果你的目标与人际关系有关，练习将你的注意力填满对方的全部。他（她）的身体、动作、话语。用你所有的感官去感受当下，并使其成为你意识的最前沿。</p><h3 id="_7-觉察的瞬间" tabindex="-1">7) 觉察的瞬间 <a class="header-anchor" href="#_7-觉察的瞬间" aria-label="Permalink to &quot;7) 觉察的瞬间&quot;">​</a></h3><p>这一切都不容易。你会失败的。事情本来就是这样。</p><p>一个干扰物会进入你的意识，你的注意力会被分散，你可能会被这个干扰物引发的负面情绪吸进去。</p><p>而你只需要一个觉察的瞬间，就能让自己从中清醒过来。</p><p>无论是在一次艰苦的锻炼中抱怨，还是因为你甚至在与对方交谈之前，就给对方虚构了一个身份，从而害怕去接近一个新人。</p><p>停下来，意识到你正在抗拒现实，然后顺其自然。</p><p>你对现实的期望并不是现实。</p><p>它不“应该”是你<em>认为</em>它应该成为的样子。</p><p><em>它本来是什么样就是什么样。</em></p><h3 id="_8-积累隐喻意义上的-训练量" tabindex="-1">8) 积累隐喻意义上的“训练量” <a class="header-anchor" href="#_8-积累隐喻意义上的-训练量" aria-label="Permalink to &quot;8) 积累隐喻意义上的“训练量”&quot;">​</a></h3><p>一切都像肌肉一样。</p><p>你的专注力、人际关系、商业、健身、灵性修行，以及任何类型的习惯。它们都会随着专注、提供表现和恢复所需充足能量，以及亲身体验而成长，这样你就可以加倍押注在对<em>你</em>_._有效的事情上。</p><p>不要指望快速见效。即使使用了“类固醇”（比如课程、辅导、方法和系统），你仍然需要积累训练量。你不可能注射点睾酮，坐在沙发上，就指望成为下一个罗尼·库尔曼（Ronnie Coleman）。</p><p>把你生活的每一个领域都当作一个科学项目来对待。</p><ul><li>识别问题</li><li>设定预期结果</li><li>测试不同的解决方案</li><li>找到有效的那一个</li><li>复制结果</li></ul><p>从那里开始，继续为了你的预期结果而去锻炼这块肌肉。然后，你就会有足够的经验来知道自己是想要增肌、减脂还是保持。</p><p>—— Dan Koe</p><p><strong>本周动态</strong></p><p>我的新课程<em>《2小时作者》（The 2 Hour Writer）</em>预售成绩极佳。它将于27号正式上线，我们已经有150多名学生在等待课程大纲的发布了。</p><p>如果你想学习一项能提升你的内容、销售、感知价值，以及你拥有的任何其他具有市场价值的技能组合，<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">请在这里查看。</a></p><p>我的最新 YouTube 视频上线了，内容是关于我实现“毫不费力生产力”的三步框架。</p><p><a href="https://youtu.be/qdXFeyzq7HE" target="_blank" rel="noreferrer">在这里观看。</a></p><p>下周，我们将在 Modern Mastery 内部举办一场饮食与生活方式工作坊。我们的目标是帮助每个人为自己的健康目标打造专属系统，无论是增肌、减脂、提升工作精力，还是仅仅为了（以一种可持续的方式）保持好身材。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Koe Letter 的读者只需支付 5 美元即可加入。</a></p><hr><p><a href="/en/letters/why-you-always-feel-overwhelmed">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',106))])}const q=r(d,[["render",u]]);export{k as __pageData,q as default};
